 void Render(){list.SuspendLayout(); foreach(Control old in list.Controls.Cast<Control>().ToArray()){list.Controls.Remove(old);old.Dispose();} var filtered=items.Where(x=>!selectedDate.HasValue || CalendarView.Occurs(x,selectedDate.Value)).Where(x=>x.Name.IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0).ToArray(); count.Text=selectedDate.HasValue?selectedDate.Value.ToString("MMMM d, yyyy",System.Globalization.CultureInfo.GetCultureInfo("en-US"))+"  ·  "+filtered.Length+(filtered.Length==1?" event":" events"):items.Count+(items.Count==1?" event":" events")+"  ·  Sorted by nearest date";clearDate.Visible=selectedDate.HasValue;calendar.Items=items;calendar.Month=visibleMonth;calendar.Selected=selectedDate;monthTitle.Text=visibleMonth.ToString("MMMM yyyy",System.Globalization.CultureInfo.GetCultureInfo("en-US"));calendar.Invalidate(); if(items.Count==0){list.Controls.Add(new Label{Text="Your next important day belongs here.\n\nSelect  + New event  to get started.",AutoSize=true,Font=new Font("Segoe UI",12),ForeColor=Color.FromArgb(111,132,155),Margin=new Padding(16,30,0,0)});} if(items.Count>0 && filtered.Length==0)list.Controls.Add(new Label{Text=selectedDate.HasValue?"No events on this date. Select New event to add one.":"No matching events. Try another search.",AutoSize=true,ForeColor=Color.Gray,Margin=new Padding(16,30,0,0)}); foreach(var item in filtered.OrderBy(x=>Math.Abs((x.Target(DateTime.Today)-DateTime.Today).Days)).ToArray()){var card=new EventCard(item);card.Margin=new Padding(9,12,12,12);card.EditRequested+=(s,e)=>Edit(item);card.DeleteRequested+=(s,e)=>{if(ConfirmDelete()){int i=items.IndexOf(item);items.RemoveAt(i);if(!Save())items.Insert(i,item);else if(floating.ContainsKey(item))floating[item].Close();Render();}};card.FloatRequested+=(s,e)=>{if(floating.ContainsKey(item)){floating[item].Show();floating[item].Activate();}else{var f=new FloatingCard(item);floating.Add(item,f);f.FormClosed+=(sender,args)=>floating.Remove(item);f.Show();}