 bool ConfirmDelete(){using(var d=new Form{Text="Delete event",ClientSize=new Size(360,150),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,StartPosition=FormStartPosition.CenterParent,BackColor=Color.White,Font=Font}){var question=new Label{Text="Delete this event?",Font=new Font("Segoe UI",13,FontStyle.Bold),ForeColor=Color.FromArgb(25,47,75),Location=new Point(24,22),AutoSize=true};var hint=new Label{Text="This cannot be undone.",ForeColor=Color.FromArgb(115,133,151),Location=new Point(26,57),AutoSize=true};var cancel=new Button{Text="Cancel",Location=new Point(160,102),Size=new Size(80,32),DialogResult=DialogResult.Cancel,FlatStyle=FlatStyle.Flat};var del=new Button{Text="Delete",Location=new Point(250,102),Size=new Size(80,32),DialogResult=DialogResult.Yes,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(176,73,82),ForeColor=Color.White};d.Controls.AddRange(new Control[]{question,hint,cancel,del});d.CancelButton=cancel;return d.ShowDialog(this)==DialogResult.Yes;}}
